mapper.select:
select p.id programId, p.title, p.thumbnail, p.description, p.online_link onlineLink, p.work_mode workMode, p.topics, p.applys, p.attendees, p.status, p.created_at createdAt from coop_programs p where p.author_brand_id = #{currentBrandId}
and locate(#{dto.q}, p.title) > 0
order by p.created_at desc

select a.id applicationId, a.applicant_brand_id applicantBrandId, a.message, a.status, a.created_at createdAt, b.brand_name applicantName, b.avator applicantAvatar, b.customer_id applicantUserId from coop_applications a inner join brand b on a.applicant_brand_id = b.id where a.program_id = #{dto.programId}
and locate(#{dto.q}, b.brand_name) > 0
and a.status = #{dto.status}
order by a.created_at desc

select a.id applicationId, a.status, a.created_at createdAt, p.id programId, p.title, p.thumbnail, p.applys, p.attendees, p.author_brand_id authorBrandId, b.brand_name authorName, b.avator authorAvatar, b.customer_id authorUserId from coop_applications a inner join coop_programs p on a.program_id = p.id inner join brand b on p.author_brand_id = b.id where a.applicant_brand_id = #{currentBrandId}
and (locate(#{dto.q}, p.title) > 0 or locate(#{dto.q}, b.brand_name) > 0)
order by a.created_at desc
